import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom input filter - only blocks obvious attack patterns
    private boolean quickSanitize(String input) {
        if (input == null) return true;
        // Block common comment sequences and UNION keyword
        String lower = input.toLowerCase();
        if (lower.contains("--") || lower.contains("/*")) return false;
        if (lower.contains("union") && lower.contains("select")) return false;
        return true;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        if (!quickSanitize(department) || !quickSanitize(sortCol)) {
            resp.sendError(400, "Invalid characters in input");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || 
            !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        String sql = buildQuery(reportType, startDate, endDate, department, sortCol);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.println("{");
            out.println("  \"results\": [");

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) out.println(",");
                out.print("    {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.printf("\"%s\": \"%s\"", 
                        meta.getColumnName(i), 
                        rs.getString(i) != null ? rs.getString(i).replace("\"", "\\\"") : "");
                }
                out.print("}");
                first = false;
            }

            out.println("\n  ]");
            out.println("}");

        } catch (SQLException e) {
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    private String buildQuery(String type, String start, String end, 
                              String dept, String sort) {
        StringBuilder sb = new StringBuilder();

        switch (type) {
            case "sales":
                sb.append("SELECT id, amount, region, sale_date FROM sales");
                break;
            case "inventory":
                sb.append("SELECT sku, quantity, warehouse, last_updated FROM inventory");
                break;
            default:
                sb.append("SELECT id, description, created_at FROM audit_log");
        }

        sb.append(" WHERE created_at BETWEEN '").append(start)
          .append("' AND '").append(end).append("'");

        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '").append(dept).append("'");
        }

        if (sort != null && !sort.isEmpty()) {
            sb.append(" ORDER BY ").append(sort);
        }

        return sb.toString();
    }
}
